create policy "Active students and teachers can read listening audio" on storage.objects for select to authenticated using ( bucket_id = 'listening-audios' and ( (select public.is_teacher_admin()) or exists ( select 1 from public.profiles p where p.id = (select auth.uid()) and p.profile_completed is true and p.enrolled is true and p.archived is not true and ( p.first_payment_same_day_required is not true or p.enrolled_at is null or p.enrolled_at::date < date '2026-11-09' or coalesce(((select public.get_my_matricula80_payment_gate())->>'payment_required')::boolean, true) is false ) ) ) );
